"use strict";var MyAccount=function(n){var t={initialize:function(){t.initEvent()},initEvent:function(){n("#btnAddUrl").on("click",function(){t.addMoreUrl()});n("#websiteInfo").on("click",".btnDeleteUrl",function(){var i=n(this);t.deleteWebsiteUrl(i)})},addMoreUrl:function(){var i=n("#websiteInfo .urlInput").length,r='<div class="form-group websiteInput"><label class="col-sm-3 control-label moreWebsiteLabel">'+LangResource.websiteUrl+" "+i+'<\/label><div class="col-sm-4"><input class="form-control urlInput" type="text" value="" /><\/div><div class="col-sm-1"><button type="button" class="btn btn-submit btnDeleteUrl">'+LangResource.deleteUrl+"<\/button><\/div><\/div>";n("#websiteInfo").append(r);t.reoderInputUrl()},deleteWebsiteUrl:function(n){var i=n.closest(".websiteInput");i.remove();t.reoderInputUrl()},reoderInputUrl:function(){var t=2;n(".moreWebsiteLabel").each(function(i,r){var u=n(r),f=LangResource.websiteUrl+" "+t;u.text(f);t++})}};return t}(jQuery);MyAccount.initialize();